"use client";

import type { ReactNode } from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

export type MeshGradientPreset = "light" | "dark";

/**
 * snap-cn palettes for the glow. Light: airy blue-tinted mist on the light
 * canvas (multiply blend). Dark: deep navy pools on the dark canvas (screen
 * blend). The blend mode is auto-picked from the background's luminance.
 */
export const MESH_GRADIENT_PRESETS: Record<
  MeshGradientPreset,
  { colors: string[]; background: string }
> = {
  light: {
    colors: ["#DCE8FE", "#EAF1FE", "#F2F6FF", "#E4E7EC"],
    background: "#FAFAFA",
  },
  dark: {
    colors: ["#12203C", "#1B2A4A", "#141417"],
    background: "#0A0A0B",
  },
};

export interface MeshGradientBgProps {
  /** Palette preset. Individual `colors` / `background` props override it. */
  preset?: MeshGradientPreset;
  /** Colors used for the radial blobs. Overrides the preset's colors. */
  colors?: string[];
  /** Base canvas color. Overrides the preset's background. */
  background?: string;
  /** Drift speed multiplier. 0.4 is a barely-moving ambient glow. */
  speed?: number;
  /** CSS blur radius (px) applied to each blob. */
  blur?: number;
  /** End-card wordmark rendered above the glow. Empty string hides the card. */
  title?: string;
  /** Muted line under the wordmark. Empty string hides it. */
  tagline?: string;
  /** Arbitrary content layered above the glow (replaces nothing — stacks with the end card). */
  children?: ReactNode;
  className?: string;
}

const FONT_FAMILY =
  'Inter, var(--font-geist-sans), -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif';

export interface MeshBlob {
  /** Center X in percent of the frame width. */
  left: number;
  /** Center Y in percent of the frame height. */
  top: number;
  /** Scale factor around 1. */
  scale: number;
}

/**
 * Pure blob layout for a time `t` in cycles. Each blob wanders on
 * incommensurate sine/cosine tracks so the field never visibly loops.
 * Deterministic: same `t` always yields the same layout.
 */
export function meshBlobLayout(t: number, count: number): MeshBlob[] {
  return Array.from({ length: count }, (_, i) => {
    const phase = i * 1.7;
    const sx = Math.sin(t * Math.PI + phase);
    const cy = Math.cos(t * Math.PI * 1.3 + phase);
    const sx2 = Math.sin(t * Math.PI * 0.7 * (2 / 3) + phase * 0.5);

    return {
      left: 50 + sx * 25,
      top: 50 + cy * 25,
      scale: 1 + sx2 * 0.2,
    };
  });
}

/**
 * Perceived-luminance check used to auto-pick the blend mode:
 * `screen` on dark canvases, `multiply` on light ones.
 */
export function isColorDark(hex: string): boolean {
  const m = hex.replace("#", "");
  if (m.length !== 6 && m.length !== 3) return true;
  const full =
    m.length === 3
      ? m
          .split("")
          .map((c) => c + c)
          .join("")
      : m;
  const r = parseInt(full.slice(0, 2), 16);
  const g = parseInt(full.slice(2, 4), 16);
  const b = parseInt(full.slice(4, 6), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance < 0.5;
}

/**
 * Pure-CSS mesh gradient: soft radial blobs drifting behind your scene.
 * No WebGL, no delayRender, no async work — every frame is plain CSS, so it
 * renders identically in the browser, in CI, and on Lambda. Use it as the
 * reliable fallback wherever a shader background is too risky to ship.
 */
export function MeshGradientBg({
  preset = "light",
  colors,
  background,
  speed = 0.4,
  blur = 120,
  title = "",
  tagline = "",
  children,
  className,
}: MeshGradientBgProps) {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const palette = MESH_GRADIENT_PRESETS[preset] ?? MESH_GRADIENT_PRESETS.light;
  const resolvedColors = colors ?? palette.colors;
  const resolvedBackground = background ?? palette.background;

  const isDark = isColorDark(resolvedBackground);
  const blendMode: "screen" | "multiply" = isDark ? "screen" : "multiply";

  // One full cycle every (2 / speed) seconds — fps-independent.
  const t = (frame / fps) * speed;
  const blobs = meshBlobLayout(t, resolvedColors.length);

  // Fast, subtle end-card entrance: ease-out fade + small rise, no bounce.
  const enter = interpolate(frame, [0, 18], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const card = isDark
    ? {
        surface: "#141417",
        border: "#26272B",
        text: "#FAFAFA",
        muted: "#A1A1AA",
        shadow: "0 24px 60px rgba(0,0,0,0.45)",
      }
    : {
        surface: "#FFFFFF",
        border: "#E4E7EC",
        text: "#101828",
        muted: "#667085",
        shadow: "0 16px 40px rgba(16,24,40,0.08)",
      };

  return (
    <AbsoluteFill
      className={className}
      style={{ background: resolvedBackground, overflow: "hidden" }}
    >
      {blobs.map((b, i) => (
        <div
          key={`blob-${resolvedColors[i]}-${i}`}
          style={{
            position: "absolute",
            left: `${b.left}%`,
            top: `${b.top}%`,
            width: "55%",
            height: "55%",
            borderRadius: "50%",
            background: `radial-gradient(circle, ${resolvedColors[i]} 0%, ${resolvedColors[i]}00 70%)`,
            filter: `blur(${blur}px)`,
            mixBlendMode: blendMode,
            transform: `translate(-50%, -50%) scale(${b.scale})`,
            willChange: "transform",
          }}
        />
      ))}
      {title !== "" ? (
        <AbsoluteFill
          style={{
            alignItems: "center",
            justifyContent: "center",
            fontFamily: FONT_FAMILY,
          }}
        >
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 10,
              padding: "44px 72px",
              borderRadius: 10,
              background: card.surface,
              border: `1px solid ${card.border}`,
              boxShadow: card.shadow,
              opacity: enter,
              transform: `translateY(${(1 - enter) * 10}px)`,
            }}
          >
            <div
              style={{
                fontSize: 52,
                fontWeight: 600,
                letterSpacing: "-0.02em",
                color: card.text,
                lineHeight: 1.1,
              }}
            >
              {title}
            </div>
            {tagline !== "" ? (
              <div
                style={{
                  fontSize: 20,
                  fontWeight: 400,
                  letterSpacing: "-0.01em",
                  color: card.muted,
                }}
              >
                {tagline}
              </div>
            ) : null}
          </div>
        </AbsoluteFill>
      ) : null}
      {children ? <AbsoluteFill>{children}</AbsoluteFill> : null}
    </AbsoluteFill>
  );
}
